import json,sys
# usage: condense.py LABEL < jsonl  > out
label=sys.argv[1]
out=sys.stdout
n=0
for line in sys.stdin.buffer:
    n+=1
    try: r=json.loads(line)
    except Exception: continue
    t=r.get('type')
    ts=r.get('timestamp','')
    if t=='queue-operation':
        if r.get('operation')=='enqueue':
            c=r.get('content')
            if isinstance(c,str):
                out.write(f"@@ {label}:{n} {ts} QUEUE-ENQUEUE\n{c}\n\n")
        continue
    m=r.get('message')
    if not isinstance(m,dict): continue
    role=m.get('role')
    c=m.get('content')
    if role=='user':
        if isinstance(c,str):
            out.write(f"@@ {label}:{n} {ts} USER\n{c}\n\n")
        elif isinstance(c,list):
            for b in c:
                if isinstance(b,dict) and b.get('type')=='text':
                    out.write(f"@@ {label}:{n} {ts} USER-TEXT\n{b.get('text')}\n\n")
    elif role=='assistant':
        if isinstance(c,list):
            for b in c:
                if isinstance(b,dict) and b.get('type')=='text':
                    out.write(f"@@ {label}:{n} {ts} ASSISTANT\n{b.get('text')}\n\n")
EOF
